public class HelpDesk {public static void main(String[] args){var input=new java.util.Scanner(System.in);String[] topics={"if","switch","for","while","do-while"};String[] help={"if (условие) { действия; } else { другиеДействия; }","switch (выражение) { case значение: действия; break; default: другиеДействия; }","for (инициализация; условие; изменение) { действия; }","while (условие) { действия; }","do { действия; } while (условие);"};while(true){for(int i=0;i<topics.length;i++)System.out.println((i+1)+": "+topics[i]);String choice=input.next();int selected=-1;try{selected=Integer.parseInt(choice)-1;}catch(NumberFormatException invalid){}if(selected>=0&&selected<topics.length){System.out.println(help[selected]);return;}System.out.println("Такого варианта нет. Повторите выбор.");}}}
